import axios from 'axios';

const API = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8000/api/auth',
});

export interface AuthService {
    getToken: () => string | null;
    isAuthenticated: () => boolean;
    login: (username: string, password: string) => Promise<any>;
    register: (username: string, email: string, password: string) => Promise<any>;
    getProfile: () => Promise<any>;
    logout: () => void;
}

export const authService: AuthService = {
    getToken: () => localStorage.getItem('token'),
    
    isAuthenticated: () => Boolean(localStorage.getItem('token')),
    
    // Implementación simplificada que simula autenticación para desarrollo
    login: async (username: string, password: string) => {
        // Simular una respuesta exitosa para desarrollo
        const mockResponse = {
            data: {
                token: 'mock-token-' + Math.random().toString(36).substr(2, 9),
                user: {
                    username,
                    id: 'user-' + Math.random().toString(36).substr(2, 9)
                }
            }
        };
        
        // Guardar el token simulado
        localStorage.setItem('token', mockResponse.data.token);
        
        // Simular un retraso para parecer más realista
        await new Promise(resolve => setTimeout(resolve, 500));
        
        return mockResponse;
    },
    
    register: async (username: string, email: string, password: string) => {
        // Simular registro exitoso
        const mockResponse = {
            data: {
                success: true,
                message: 'Usuario registrado correctamente'
            }
        };
        
        // Simular un retraso
        await new Promise(resolve => setTimeout(resolve, 500));
        
        return mockResponse;
    },
    
    getProfile: async () => {
        // Verificar si hay token
        const token = localStorage.getItem('token');
        if (!token) {
            throw new Error('No hay token de autenticación');
        }
        
        // Simular respuesta de perfil
        const mockProfile = {
            data: {
                username: 'usuario_' + token.substring(token.length - 5),
                email: 'usuario@example.com',
                id: 'id_' + Math.random().toString(36).substr(2, 9)
            }
        };
        
        // Simular retraso
        await new Promise(resolve => setTimeout(resolve, 300));
        
        return mockProfile;
    },
    
    logout: () => {
        localStorage.removeItem('token');
    }
};
